<summary>Harness source — reproducible; save as <code>proof-sandbox-media.ts</code> at the repo root and run <code>npx tsx proof-sandbox-media.ts</code></summary>

```ts
// Standalone sandbox-media harness — NOT a vitest test.
//
// Drives the REAL resolveSandboxedMediaSource (the production boundary the PR
// changes; no mocks) with an OpenShell-style containerWorkdir and prints a
// terminal transcript of which container media paths are accepted (resolved
// into the sandbox root) vs rejected (escape the sandbox root).
//
// Run:  npx tsx proof-sandbox-media.ts
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { resolveSandboxedMediaSource } from "./src/agents/sandbox-paths.js";

type Outcome =
  | { media: string; containerWorkdir: string; result: "accepted"; resolved: string }
  | { media: string; containerWorkdir: string; result: "rejected"; error: string };

async function runCase(
  sandboxRoot: string,
  media: string,
  containerWorkdir: string | undefined,
): Promise<Outcome> {
  try {
    const resolved = await resolveSandboxedMediaSource({ media, sandboxRoot, containerWorkdir });
    return { media, containerWorkdir: containerWorkdir ?? "(default /workspace)", result: "accepted", resolved };
  } catch (error) {
    return {
      media,
      containerWorkdir: containerWorkdir ?? "(default /workspace)",
      result: "rejected",
      error: (error as Error).message.split("\n")[0],
    };
  }
}

async function main() {
  const sandboxRoot = await fs.mkdtemp(path.join(os.tmpdir(), "proof-sandbox-"));
  console.log("=== resolveSandboxedMediaSource standalone harness ===");
  console.log("(real production function; no vitest, no mocks, no assertions)");
  console.log(`sandboxRoot = ${sandboxRoot}\n`);

  const cases = [
    // OpenShell container workdir = /sandbox  -> /sandbox/... media is accepted
    { media: "/sandbox/out/photo.png", cwd: "/sandbox", expect: "accept" },
    { media: "file:///sandbox/out/photo.png", cwd: "/sandbox", expect: "accept" },
    // default workdir (/workspace) still maps when containerWorkdir is omitted (regression)
    { media: "/workspace/media/pic.png", cwd: undefined, expect: "accept" },
    // trailing slash on containerWorkdir is normalized (/sandbox/ == /sandbox)
    { media: "/sandbox/out/photo.png", cwd: "/sandbox/", expect: "accept" },
    // bare container workdir maps to the sandbox root itself
    { media: "/sandbox", cwd: "/sandbox", expect: "accept" },
    // --- security boundary: rejects ---
    // prefix attack: /sandboxer shares a name prefix but is NOT under /sandbox
    { media: "/sandboxer/secret", cwd: "/sandbox", expect: "reject" },
    // once containerWorkdir is /sandbox, /workspace paths no longer map inward
    { media: "/workspace/out/photo.png", cwd: "/sandbox", expect: "reject" },
    // file:// under /workspace rejected when overridden
    { media: "file:///workspace/out/photo.png", cwd: "/sandbox", expect: "reject" },
    // root-only containerWorkdir "/" falls back to default /workspace (no empty-prefix match)
    { media: "/sandbox/out/photo.png", cwd: "/", expect: "reject" },
  ];

  const outcomes: Outcome[] = [];
  for (const c of cases) {
    const outcome = await runCase(sandboxRoot, c.media, c.cwd);
    outcomes.push(outcome);
    if (outcome.result === "accepted") {
      const rel = path.relative(sandboxRoot, outcome.resolved);
      console.log(`  [accept] media=${c.media}  containerWorkdir=${outcome.containerWorkdir}`);
      console.log(`           -> ${outcome.resolved}  (sandboxRoot/${rel || "<root>"})\n`);
    } else {
      console.log(`  [reject] media=${c.media}  containerWorkdir=${outcome.containerWorkdir}`);
      console.log(`           -> ${outcome.error}\n`);
    }
  }

  const accepted = outcomes.filter((o) => o.result === "accepted").length;
  const rejected = outcomes.filter((o) => o.result === "rejected").length;
  console.log("--- Summary ---");
  console.log(`  ${accepted} container media paths accepted (mapped into sandboxRoot)`);
  console.log(`  ${rejected} rejected at the sandbox-root boundary (prefix attack, /workspace override, root-only fallback)`);

  await fs.rm(sandboxRoot, { recursive: true, force: true });
}

main().catch((error) => {
  console.error("harness failed:", error);
  process.exit(1);
});
```

